  function addBuilding(block, x, y, w, h, levels, name) {
    const district = DISTRICTS[block.district];
    const building = {
      x, y, w, h, levels,
      name: name ?? null,
      landmark: false,
      district: block.district,
      roof: random.pick(district.roofs),
      seed: random.int(0, 100000),
      block,
    };
