      lanes.push({ x1: vRoads[i].x - laneOff, y1: hRoads[j].y, x2: vRoads[i].x - laneOff, y2: hRoads[j + 1].y, dirX: 0, dirY: 1, axis: 'v', road: i, segment: j });
