  if (car.police && car.lightsOn !== false) {
    const phase = (car.lightPhase ?? 0) % 1;
    ctx.fillStyle = phase < 0.5 ? 'rgba(255,59,48,0.20)' : 'rgba(59,130,246,0.20)';
    ctx.beginPath();
