  ctx.fillStyle = car.color;
  ctx.fill();
  roundRectPath(ctx, -L / 2 + 3, -W / 2 + 3, L - 6, W - 6, 4);
  ctx.fillStyle = shadeColor(car.color, 1.1);
  ctx.fill();

