  ctx.fillStyle = '#22303c';
  roundRectPath(ctx, -L * 0.1, -W * 0.37, L * 0.36, W * 0.74, 4);
  ctx.fill();
  ctx.fillStyle = 'rgba(150,200,225,0.75)';
