    ctx.fillStyle = '#20242a';
    ctx.fillRect(-L * 0.08, -W / 2 + 2, L * 0.4, 4);
    ctx.fillRect(-L * 0.08, W / 2 - 6, L * 0.4, 4);
    ctx.fillStyle = '#20242a';
    ctx.font = `700 ${Math.round(W * 0.34)}px sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
