    ctx.fill();
  }
  if (car.typeId === 'taxi') {
    ctx.fillStyle = '#fff3cf';
    roundRectPath(ctx, -4, -5, 9, 10, 2);
    ctx.fill();
    ctx.fillStyle = '#8a6d1c';
    ctx.fillRect(-4, -1, 9, 2);
  }

