    ctx.fill();
    ctx.fillStyle = ped.shirt;
    roundRectPath(ctx, -3, -5, 12, 10, 4);
    ctx.fill();
    ctx.fillStyle = ped.skin;
    ctx.beginPath();
    ctx.arc(13, 0, 4.6, 0, Math.PI * 2);
    ctx.fill();
