  const steps = Math.max(1, Math.floor(dist / 26));
  for (let i = 1; i < steps; i += 1) {
    const t = i / steps;
    if (world.circleBlocked(x1 + (x2 - x1) * t, y1 + (y2 - y1) * t, 2)) return false;
