    if (!progress.storyDone && progress.storyIndex < STORY.length) {
      const at = poi(STORY[progress.storyIndex].startKind);
      list.push({ kind: 'story', x: at.x, y: at.y, label: STORY[progress.storyIndex].title });
    }
